  var last = numbers.pop()
  for (var j = 0; j < numbers.length; j++) if (numbers[j] > 255) return -1
  if (last >= Math.pow(256, 4 - numbers.length)) return -1
  var value = last
  for (var k = 0; k < numbers.length; k++) value += numbers[k] * Math.pow(256, 3 - k)
