  if (user.length > MAX_XTREAM_FIELD) return fail("user_too_long", "username")
  if (hasControlChar(o.password)) return fail("pass_control", "password")
  var pass = sanitizeInput(o.password, MAX_XTREAM_FIELD + 1)
